// final class ListNode { var val: Int; var next: ListNode?; init(_ v: Int, _ n: ListNode? = nil) { val = v; next = n } }
func mergeTwoLists(_ a: ListNode?, _ b: ListNode?) -> ListNode? {
    let dummy = ListNode(0)
    var tail = dummy, l1 = a, l2 = b
    while let x = l1, let y = l2 {
        if x.val <= y.val { tail.next = x; l1 = x.next } else { tail.next = y; l2 = y.next }
        tail = tail.next!
    }
    tail.next = l1 ?? l2
    return dummy.next
}
